  let saved='';try{saved=localStorage.getItem(projectSelectionKey(uid))||'';}catch{}
  const currentExists=projects.some(p=>p.id===pid);
  const next=currentExists?pid:(saved&&projects.some(p=>p.id===saved)?saved:projects[0].id);
  if(next!==pid)setPid(next);
  try{localStorage.setItem(projectSelectionKey(uid),next);}catch{}
