 const [moveMode,setMoveMode]=useState(false);const [undoModel,setUndoModel]=useState<{pid:string;floors?:Floor[];elements:Element[];activities:Activity[]}|null>(null);
 const [newCategory,setNewCategory]=useState<Category>('footing');
 const [modelPartsExpanded,setModelPartsExpanded]=useState(true);
 const [expandedCategories,setExpandedCategories]=useState<Set<string>>(new Set());const [expandedGroups,setExpandedGroups]=useState<Set<string>>(new Set(Object.keys(categoryGroups)));
  const [selected,setSelected]=useState('F-001');const [chatFocusRequest,setChatFocusRequest]=useState(0);const element=project.elements.find(e=>e.id===selected);
 const [hidden,setHidden]=useState<Set<string>>(new Set());const [hiddenFloors,setHiddenFloors]=useState<Set<number>>(new Set());const [selectedFloors,setSelectedFloors]=useState<Set<number>>(new Set());const [explodeFloors,setExplodeFloors]=useState(false);const [floorGap,setFloorGap]=useState(3);const [isolate,setIsolate]=useState(false);const [transparent,setTransparent]=useState(false);const [xray,setXray]=useState(false);const [rebar,setRebar]=useState(false);const [section,setSection]=useState(false);const [direction,setDirection]=useState('ISO');const [cameraRevision,setCameraRevision]=useState(0);const [ortho,setOrtho]=useState(false);const [mode,setMode]=useState<'3d'|'4d'>('3d');const [date,setDate]=useState('2026-12-05');const [playing,setPlaying]=useState(false);const [mobile,setMobile]=useState('model');const [modal,setModal]=useState<'project'|'documents'|'help'|'schedule'|'cloud'|'ai'|'admin'|'share'|null>(null);const [newName,setNewName]=useState('');const [toast,setToast]=useState('');const [saved,setSaved]=useState(true);const [saveError,setSaveError]=useState(false);const [draft,setDraft]=useState<Element|null>(null);const [preview,setPreview]=useState<{name:string;url:string;type:string}|null>(null);const [ifcSource,setIfcSource]=useState<IfcViewerSource|null>(null);const [ifcStatus,setIfcStatus]=useState<IfcViewerStatus|null>(null);const rebarBeforeXray=useRef<boolean|null>(null);const transparentBeforeXray=useRef<boolean|null>(null);const fileInput=useRef<HTMLInputElement>(null);const jsonInput=useRef<HTMLInputElement>(null);const controls=useRef<any>(null);
 const start=project.activities.length?project.activities.reduce((s,a)=>a.start<s?a.start:s,project.activities[0].start):dateRange.start;const end=project.activities.length?project.activities.reduce((s,a)=>a.end>s?a.end:s,project.activities[0].end):dateRange.end;const maxDays=Math.max(1,dayNumber(end)-dayNumber(start));
 const floorGroups=useMemo<Floor[]>(()=>{const byIndex=new Map<number,Floor>();for(const floor of project.floors||[])if(Number.isInteger(floor.index))byIndex.set(floor.index,floor);for(const item of project.elements){const index=Number.isInteger(item.floor)?(item.floor as number):0;if(!byIndex.has(index))byIndex.set(index,{id:'FLOOR-'+index,name:index===0?'ชั้น 1':`ชั้น ${index+1}`,index,elevation:index*3,height:3});}if(!byIndex.size)byIndex.set(0,{id:'FLOOR-0',name:'ชั้น 1',index:0,elevation:0,height:3});return [...byIndex.values()].sort((a,b)=>a.index-b.index)},[project.floors,project.elements]);
 const floorIndexFor=(item:Element)=>Number.isInteger(item.floor)?(item.floor as number):(floorGroups[0]?.index??0);
 const isFloorSelected=(index:number)=>selectedFloors.size===0||selectedFloors.has(index);
 const filteredElements=useMemo(()=>project.elements.filter(item=>isFloorSelected(floorIndexFor(item))),[project.elements,selectedFloors,floorGroups]);
 const [modelAddOpen,setModelAddOpen]=useState(false);
 const [modelAddSize,setModelAddSize]=useState<[number,number,number]>([...defaults.footing] as [number,number,number]);const [modelAddRebar,setModelAddRebar]=useState(false);const [modelAddRebarDiameter,setModelAddRebarDiameter]=useState(.016);const [modelAddRebarSpacing,setModelAddRebarSpacing]=useState(.2);const [modelAddRebarType,setModelAddRebarType]=useState('DB12');
 useEffect(()=>{if(modelAddOpen)setModelAddSize(defaultSizeFor(newCategory))},[newCategory]);
 const selectAllFloors=()=>setSelectedFloors(new Set());
 const toggleFloorSelection=(index:number)=>setSelectedFloors(current=>{const next=current.size?new Set(current):new Set(floorGroups.map(floor=>floor.index));if(next.size===1&&next.has(index))return current;next.has(index)?next.delete(index):next.add(index);return next.size===floorGroups.length?new Set():next});
 const floorShiftFor=(item:Element)=>{if(!explodeFloors)return 0;const order=floorGroups.findIndex(floor=>floor.index===floorIndexFor(item));return Math.max(0,order)*floorGap};
 useEffect(()=>{setSaved(!store.saving);setSaveError(!!store.error);},[store.saving,store.error]);
 useEffect(()=>{if(toast){const t=setTimeout(()=>setToast(''),4000);return()=>clearTimeout(t)}},[toast]);
 const draftBase=useRef<Element|null>(null);
 useEffect(()=>{draftBase.current=element?structuredClone(element):null;setDraft(draftBase.current)},[selected,project.id]);
 useEffect(()=>{if(!element)return;setDraft(previous=>{if(!previous||JSON.stringify(previous)===JSON.stringify(draftBase.current)){draftBase.current=structuredClone(element);return structuredClone(element);}return previous;});},[element?.revision]);
  useEffect(()=>{if(draft?.category==='footing'&&draft.cover===undefined)setDraft(previous=>previous?{...previous,cover:.075}:previous)},[draft?.id]);
  useEffect(()=>{setPlaying(false);setDate(start);setHidden(new Set());setHiddenFloors(new Set());setSelectedFloors(new Set());setExplodeFloors(false);setExpandedCategories(new Set());setModelPartsExpanded(true);setIsolate(false);setXray(false);setIfcSource(null);setIfcStatus(null);setDirection('ISO');setCameraRevision(r=>r+1);rebarBeforeXray.current=null;transparentBeforeXray.current=null},[pid]);
  useEffect(()=>{if(ifcSource&&!project.documents.some(d=>d.id===ifcSource.id))setIfcSource(null)},[ifcSource,project.documents]);
 useEffect(()=>{if(mode==='4d')setHidden(new Set());else setPlaying(false)},[mode]);
 useEffect(()=>{if(!playing)return;const t=setInterval(()=>setDate(d=>{if(d>=end){setPlaying(false);return end}return new Date((dayNumber(d)+1)*86400000).toISOString().slice(0,10)}),250);return()=>clearInterval(t)},[playing,end]);
 useEffect(()=>()=>{if(preview)URL.revokeObjectURL(preview.url)},[preview]);
 const update=(fn:(p:Project)=>Project)=>{const next=fn(project);const changed=(key:keyof Project)=>JSON.stringify(next[key])!==JSON.stringify(project[key]);if((changed('elements')&&!canUse(userProfile,'model'))||(changed('activities')&&!canUse(userProfile,'schedule'))||(changed('documents')&&!canUse(userProfile,'documents'))||(changed('description')&&!canUse(userProfile,'projects'))){setToast('Role ของคุณไม่มีสิทธิ์แก้ไขข้อมูลส่วนนี้');return;}setSaved(false);store.update(project.id,fn);};
 const notify=(s:string)=>setToast(s);
 const handleIfcStatus=useCallback((status:IfcViewerStatus|null)=>setIfcStatus(status),[]);
 const aiStatus=ai.job?.status,aiJobId=ai.job?.id;const aiSeen=useRef<string|null>(null);
 useEffect(()=>{if(!aiJobId)return;if(aiStatus==='running'){aiSeen.current=aiJobId;return}if(aiSeen.current!==aiJobId)return;aiSeen.current=null;if(modal!=='ai'&&ai.job?.mode!=='edit')setToast(aiStatus==='done'?'AI สร้างโมเดลเสร็จแล้ว กดไอคอนด้านบนเพื่อเปิดตรวจ':'AI สร้างโมเดลไม่สำเร็จ กดไอคอนด้านบนเพื่อดูสาเหตุ')},[aiStatus,aiJobId]);const toggle=(c:string)=>setHidden(h=>{const n=new Set(h);n.has(c)?n.delete(c):n.add(c);return n});
 const toggleCategory=(c:string)=>setExpandedCategories(expanded=>{const next=new Set(expanded);next.has(c)?next.delete(c):next.add(c);return next});const toggleGroup=(groupKey:string)=>setExpandedGroups(expanded=>{const next=new Set(expanded);next.has(groupKey)?next.delete(groupKey):next.add(groupKey);return next});
 const selectProject=(id:string)=>{if(usersView)navigate('/dashboard');setPid(id);setSelected('F-001');setDirection('ISO');setCameraRevision(r=>r+1);setModal(null);setMobile('model')};
 const rememberModel=()=>setUndoModel({pid:project.id,floors:structuredClone(project.floors),elements:structuredClone(project.elements),activities:structuredClone(project.activities)});
 const commitMove=(position:[number,number,number])=>{if(!element)return;try{const elements=editedElements(project.elements,{...element,position}) as Element[];rememberModel();update(p=>({...p,elements}));}catch(e){notify(String(e))}};
 const removeMember=()=>{if(!element)return;rememberModel();const ids=new Set([element.id,...project.elements.filter(e=>e.hostId===element.id).map(e=>e.id)]);update(p=>({...p,elements:p.elements.filter(e=>!ids.has(e.id)),activities:p.activities.map(a=>({...a,...(a.elementIds?{elementIds:a.elementIds.filter(id=>!ids.has(id))}:{})}))}));setSelected('');notify('ลบชิ้นส่วนแล้ว ย้อนกลับได้');};
 const saveElement=()=>{if(draft&&element&&draft.revision!==element.revision){notify('ชิ้นส่วนนี้มีรุ่นใหม่ ข้อมูลที่กรอกยังอยู่ กรุณาตรวจรุ่นล่าสุดก่อนบันทึก');return;}if(!draft||!draft.name.trim()){notify('กรุณาระบุชื่อชิ้นส่วน');return}const normalizedDraft={...draft,name:draft.name.trim()};if(!validateElement(normalizedDraft)){notify('ขนาดต้องมากกว่า 0 และตำแหน่งต้องเป็นตัวเลข');return}let edited:Element[];try{edited=editedElements(project.elements,normalizedDraft) as Element[]}catch(e){notify(e instanceof Error?e.message:String(e));return}rememberModel();update(p=>({...p,elements:edited,audit:[{at:new Date().toISOString(),message:`แก้ไข ${normalizedDraft.id} → รุ่น ${(element?.revision||0)+1}`},...p.audit].slice(0,100)}));setDraft(normalizedDraft);notify('บันทึกชิ้นส่วนแล้ว')};
 const createMember=()=>{const id=newCategory.toUpperCase()+'-'+crypto.randomUUID().slice(0,6);const selectedFloor=selectedFloors.size===1?[...selectedFloors][0]:undefined;const e:Element={id,category:newCategory,name:labels[newCategory]+'ใหม่',size:[...modelAddSize] as [number,number,number],position:[10+project.elements.filter(e=>e.source==='กรอกโดยผู้ใช้').length*7,0,modelAddSize[2]/2],zone:'A',material:defaultMaterials[newCategory]||'ตามแบบ',source:'กรอกโดยผู้ใช้',revision:1,floor:selectedFloor,barDiameter:modelAddRebar?modelAddRebarDiameter:undefined,barSpacing:modelAddRebar?modelAddRebarSpacing:undefined,properties:modelAddRebar?{'ชนิดเหล็ก':modelAddRebarType}:undefined};rememberModel();update(p=>({...p,elements:[...p.elements,e]}));setSelected(id);setSelectedFloors(new Set());setExpandedCategories(expanded=>new Set([...expanded,newCategory]));setIsolate(false);setHidden(h=>new Set([...h].filter(c=>c!==newCategory)));notify('เพิ่ม'+labels[newCategory]+'แล้ว แก้ขนาดและตำแหน่งได้')};
